SELECT DISTINCT m.* FROM system_menus m
INNER JOIN system_role_menus rm ON m.id = rm.menu_id INNER JOIN system_user_roles ur ON rm.role_id = ur.role_id WHERE ur.user_id = #{userId}
ORDER BY m.sort

